    requires_python = re.search(r'^\s*requires-python\s*=\s*["\']([^"\']+)["\']', text, re.M)
    if requires_python:
        print("PYPROJECT_REQUIRES_PYTHON", requires_python.group(1))
    poetry_python = re.search(r'^\s*python\s*=\s*["\']([^"\']+)["\']', text, re.M)
    if poetry_python:
