                lines.append(stripped)
        elif is_marker_line and any(term in line_lower for term in suspicious_terms):
            lines.append(stripped)
    if not lines:
        continue
    detail = " | ".join(lines[:4])
    key = (name, detail)
    if key in reported:
        continue
    reported.add(key)
    print("LOCK_PLATFORM_PACKAGE", name, detail[:260])

