SKIP_DIRS = {
    ".git", ".venv", "venv", "__pycache__", ".mypy_cache", ".pytest_cache",
    "node_modules", "dist", "build", "logs", "docs"
}
COMMON_OPTIONAL = {
    "pytest", "typing_extensions", "setuptools", "pkg_resources", "yaml", "dotenv",
    "PIL", "cv2", "sklearn", "bs4", "jinja2", "dateutil", "click"
}

